public static long findKthSmallest(int N, int M, long K) {
    long count = 0;
    long number = 0;

    while (count < K) {
        number++;
        boolean divisibleByN = (number % N == 0);
        boolean divisibleByM = (number % M == 0);

        if (divisibleByN ^ divisibleByM) { // XOR to check exactly one is true
            count++;
        }
    }

    return number;
}
